// Pipeline corner-case integration testbench.
//
// Complements processor_tb (which covers the baseline dependent/independent,
// single load-use, BEQ/BNE and three-ADDI programs and the performance
// counters). Each riscv_top instance below runs one program from
// programs/verif_*.hex (generated by verification/gen_corner_programs.py)
// and targets one verification-matrix row in docs/verification.md:
//
//   u_x0     x0 write/forward/bypass/load-use protection
//   u_fwd    forwarding priority (EX/MEM over MEM/WB, per operand, store data/base)
//   u_chain  long chain of back-to-back dependent instructions
//   u_lu     load-use stalls on rs1, rs2, store data, store base, branch; false hazards
//   u_br     branch flushing: backward loop, forwarded branch operands,
//            wrong-path store/branch/register-write suppression
//   u_rst    mid-program reset with a store and a register write in flight
//   u_rst_ref  same program as u_rst, cold reset only (golden reference)
//
// pipeline_invariant_monitor is attached to every instance and checks the
// cycle-level invariants after every clock edge.

module pipeline_invariant_monitor #(
    parameter string NAME = "dut"
) (
    input logic        clk,
    input logic        rst_n,
    input logic [31:0] pc_current,
    input logic [31:0] ifid_instruction,
    input logic        ex_branch_taken,
    input logic        load_use_stall,
    input logic        idex_reg_write,
    input logic        idex_mem_read,
    input logic        idex_mem_write,
    input logic        idex_branch,
    input logic [4:0]  idex_rs1,
    input logic [4:0]  idex_rs2,
    input logic [1:0]  forward_a,
    input logic [1:0]  forward_b,
    input logic        wb_reg_write,
    input logic [4:0]  wb_rd,
    input logic        memwb_perf_valid,
    input logic        exmem_mem_write,
    input logic        exmem_perf_valid,
    output integer     stall_events,
    output integer     flush_events
);
    localparam logic [31:0] NOP = 32'h0000_0013;

    logic        prev_taken;
    logic        prev_stall;
    logic [31:0] prev_pc;
    logic [31:0] prev_ifid;

    initial begin
        stall_events = 0;
        flush_events = 0;
        prev_taken = 1'b0;
        prev_stall = 1'b0;
        prev_pc = '0;
        prev_ifid = NOP;
    end

    // Sampled on the falling edge, half a cycle after each rising edge.
    always @(negedge clk) begin
        if (!rst_n) begin
            prev_taken <= 1'b0;
            prev_stall <= 1'b0;
            stall_events <= 0;
            flush_events <= 0;
        end else begin
            // Taken branch in EX on the previous edge: both younger instructions
            // (IF/ID and the one being fetched) must have been squashed.
            if (prev_taken) begin
                if (ifid_instruction !== NOP)
                    $fatal(1, "%s: IF/ID not flushed after taken branch (holds %h)",
                           NAME, ifid_instruction);
                if (idex_reg_write || idex_mem_read || idex_mem_write || idex_branch)
                    $fatal(1, "%s: ID/EX not a bubble after taken branch", NAME);
            end

            // Load-use stall on the previous edge: PC and IF/ID hold, ID/EX bubbles.
            if (prev_stall) begin
                if (pc_current !== prev_pc)
                    $fatal(1, "%s: PC advanced during load-use stall (%h -> %h)",
                           NAME, prev_pc, pc_current);
                if (ifid_instruction !== prev_ifid)
                    $fatal(1, "%s: IF/ID changed during load-use stall", NAME);
                if (idex_reg_write || idex_mem_read || idex_mem_write || idex_branch)
                    $fatal(1, "%s: load-use stall did not inject an ID/EX bubble", NAME);
            end

            // x0 is never a forwarding source.
            if (forward_a != 2'b00 && idex_rs1 == 5'd0)
                $fatal(1, "%s: forward_a=%b selected for rs1=x0", NAME, forward_a);
            if (forward_b != 2'b00 && idex_rs2 == 5'd0)
                $fatal(1, "%s: forward_b=%b selected for rs2=x0", NAME, forward_b);

            // Side effects only from instructions the validity tracker considers
            // live (i.e. never from flushed or bubble slots).
            if (wb_reg_write && wb_rd != 5'd0 && !memwb_perf_valid)
                $fatal(1, "%s: register write x%0d from a non-valid slot", NAME, wb_rd);
            if (exmem_mem_write && !exmem_perf_valid)
                $fatal(1, "%s: memory write from a non-valid slot", NAME);

            if (load_use_stall)
                stall_events <= stall_events + 1;
            if (ex_branch_taken)
                flush_events <= flush_events + 1;

            prev_taken <= ex_branch_taken;
            prev_stall <= load_use_stall && !ex_branch_taken;
            prev_pc <= pc_current;
            prev_ifid <= ifid_instruction;
        end
    end
endmodule

`define ATTACH_MONITOR(MON, INST, RST, SE, FE) \
    pipeline_invariant_monitor #(.NAME(`"INST`")) MON ( \
        .clk(clk), .rst_n(RST), \
        .pc_current(INST.pc_current), .ifid_instruction(INST.ifid_instruction), \
        .ex_branch_taken(INST.ex_branch_taken), .load_use_stall(INST.load_use_stall), \
        .idex_reg_write(INST.idex_reg_write), .idex_mem_read(INST.idex_mem_read), \
        .idex_mem_write(INST.idex_mem_write), .idex_branch(INST.idex_branch), \
        .idex_rs1(INST.idex_rs1), .idex_rs2(INST.idex_rs2), \
        .forward_a(INST.forward_a), .forward_b(INST.forward_b), \
        .wb_reg_write(INST.wb_reg_write), .wb_rd(INST.wb_rd), \
        .memwb_perf_valid(INST.memwb_perf_valid), \
        .exmem_mem_write(INST.exmem_mem_write), .exmem_perf_valid(INST.exmem_perf_valid), \
        .stall_events(SE), .flush_events(FE))

`define EXPECT_REG(INST, IDX, VALUE) \
    if (INST.u_register_file.registers[IDX] !== 32'(VALUE)) \
        $fatal(1, `"INST: x%0d expected %h, got %h`", IDX, 32'(VALUE), \
               INST.u_register_file.registers[IDX]);

`define EXPECT_MEM(INST, WORD, VALUE) \
    if (INST.u_data_memory.words[WORD] !== 32'(VALUE)) \
        $fatal(1, `"INST: M[%0d] expected %h, got %h`", (WORD) * 4, 32'(VALUE), \
               INST.u_data_memory.words[WORD]);

`define EXPECT_COUNTERS(INST, SE, FE, RETIRED, STALLS, TAKEN, NOT_TAKEN) \
    if (INST.perf_instructions_retired != 64'(RETIRED) || \
        INST.perf_stall_cycles != 64'(STALLS) || \
        INST.perf_branch_flushes != 64'(TAKEN) || \
        INST.perf_taken_branches != 64'(TAKEN) || \
        INST.perf_not_taken_branches != 64'(NOT_TAKEN) || \
        SE != (STALLS) || FE != (TAKEN)) \
        $fatal(1, `"INST: retired=%0d stalls=%0d (monitor %0d) flushes=%0d (monitor %0d) taken=%0d not_taken=%0d`", \
               INST.perf_instructions_retired, INST.perf_stall_cycles, SE, \
               INST.perf_branch_flushes, FE, INST.perf_taken_branches, \
               INST.perf_not_taken_branches);

`define EXPECT_RESET_STATE(INST) \
    if (INST.pc_current !== 32'd0 || INST.ifid_instruction !== 32'h0000_0013 || \
        INST.idex_reg_write !== 1'b0 || INST.idex_mem_read !== 1'b0 || \
        INST.idex_mem_write !== 1'b0 || INST.idex_branch !== 1'b0 || \
        INST.exmem_reg_write !== 1'b0 || INST.exmem_mem_write !== 1'b0 || \
        INST.exmem_mem_read !== 1'b0 || INST.wb_reg_write !== 1'b0 || \
        INST.ex_branch_taken !== 1'b0 || INST.load_use_stall !== 1'b0 || \
        INST.perf_instructions_retired != 0 || INST.perf_stall_cycles != 0 || \
        INST.perf_total_cycles != 0 || INST.perf_branch_flushes != 0) \
        $fatal(1, `"INST: pipeline not in reset state (pc=%h ifid=%h)`", \
               INST.pc_current, INST.ifid_instruction);

module pipeline_corner_tb;
    logic clk;
    logic rst_n;
    logic rst_n_mid;

    integer x0_se, x0_fe, fwd_se, fwd_fe, chain_se, chain_fe;
    integer lu_se, lu_fe, br_se, br_fe, rst_se, rst_fe, ref_se, ref_fe;

    logic [31:0] x0_reg0_after_reset;
    logic [5:0]  fwd_seen;
    logic [7:0]  chain_seen;
    integer      br_x3_writes;
    integer      rst_writes_after_restart;
    logic        rst_restarted;
    logic [31:0] rst_snapshot [1:5];

    riscv_top #(.IMEM_INIT_FILE("programs/verif_x0_protection.hex"))
        u_x0 (.clk(clk), .rst_n(rst_n));
    riscv_top #(.IMEM_INIT_FILE("programs/verif_forward_priority.hex"))
        u_fwd (.clk(clk), .rst_n(rst_n));
    riscv_top #(.IMEM_INIT_FILE("programs/verif_dependency_chain.hex"))
        u_chain (.clk(clk), .rst_n(rst_n));
    riscv_top #(.IMEM_INIT_FILE("programs/verif_load_use.hex"))
        u_lu (.clk(clk), .rst_n(rst_n));
    riscv_top #(.IMEM_INIT_FILE("programs/verif_branch_flush.hex"))
        u_br (.clk(clk), .rst_n(rst_n));
    riscv_top #(.IMEM_INIT_FILE("programs/verif_reset.hex"))
        u_rst (.clk(clk), .rst_n(rst_n_mid));
    riscv_top #(.IMEM_INIT_FILE("programs/verif_reset.hex"))
        u_rst_ref (.clk(clk), .rst_n(rst_n));

    `ATTACH_MONITOR(m_x0, u_x0, rst_n, x0_se, x0_fe);
    `ATTACH_MONITOR(m_fwd, u_fwd, rst_n, fwd_se, fwd_fe);
    `ATTACH_MONITOR(m_chain, u_chain, rst_n, chain_se, chain_fe);
    `ATTACH_MONITOR(m_lu, u_lu, rst_n, lu_se, lu_fe);
    `ATTACH_MONITOR(m_br, u_br, rst_n, br_se, br_fe);
    `ATTACH_MONITOR(m_rst, u_rst, rst_n_mid, rst_se, rst_fe);
    `ATTACH_MONITOR(m_rst_ref, u_rst_ref, rst_n, ref_se, ref_fe);

    always #5 clk = ~clk;

    initial begin
        #20000;
        $fatal(1, "pipeline_corner_tb timed out");
    end

    // Program-specific cycle checks, sampled when the instruction of interest
    // is in EX (identified by its destination register).
    always @(negedge clk) begin
        if (rst_n) begin
            // ---- Forwarding priority (u_fwd) ----
            if (u_fwd.idex_reg_write) begin
                case (u_fwd.idex_rd)
                    5'd2: begin // add x2, x1, x1: younger x1 in EX/MEM, older in MEM/WB
                        if (u_fwd.forward_a != 2'b10 || u_fwd.forward_b != 2'b10 ||
                            u_fwd.ex_alu_result != 32'd4)
                            $fatal(1, "u_fwd: add x2 priority a=%b b=%b result=%0d",
                                   u_fwd.forward_a, u_fwd.forward_b, u_fwd.ex_alu_result);
                        fwd_seen[0] <= 1'b1;
                    end
                    5'd6: begin // sub x6, x5, x4: rs1 EX/MEM, rs2 MEM/WB
                        if (u_fwd.forward_a != 2'b10 || u_fwd.forward_b != 2'b01)
                            $fatal(1, "u_fwd: sub x6 a=%b b=%b", u_fwd.forward_a, u_fwd.forward_b);
                        fwd_seen[1] <= 1'b1;
                    end
                    5'd10: begin // sub x10, x8, x9: rs1 MEM/WB, rs2 EX/MEM
                        if (u_fwd.forward_a != 2'b01 || u_fwd.forward_b != 2'b10)
                            $fatal(1, "u_fwd: sub x10 a=%b b=%b", u_fwd.forward_a, u_fwd.forward_b);
                        fwd_seen[2] <= 1'b1;
                    end
                    5'd12: begin // sub x12, x0, x11: rs2-only priority
                        if (u_fwd.forward_a != 2'b00 || u_fwd.forward_b != 2'b10)
                            $fatal(1, "u_fwd: sub x12 a=%b b=%b", u_fwd.forward_a, u_fwd.forward_b);
                        fwd_seen[3] <= 1'b1;
                    end
                    default: ;
                endcase
            end
            if (u_fwd.idex_mem_write) begin
                if (u_fwd.idex_rs1 == 5'd0) begin // sw x14, 4(x0): store-data priority
                    if (u_fwd.forward_b != 2'b10 || u_fwd.ex_forwarded_rs2 != 32'h66)
                        $fatal(1, "u_fwd: sw x14 store data b=%b data=%h",
                               u_fwd.forward_b, u_fwd.ex_forwarded_rs2);
                    fwd_seen[4] <= 1'b1;
                end else begin // sw x9, 0(x15): base from EX/MEM
                    if (u_fwd.forward_a != 2'b10 || u_fwd.ex_alu_result != 32'd8)
                        $fatal(1, "u_fwd: sw base a=%b addr=%h",
                               u_fwd.forward_a, u_fwd.ex_alu_result);
                    fwd_seen[5] <= 1'b1;
                end
            end

            // ---- Dependency chain (u_chain) ----
            if (u_chain.idex_reg_write && u_chain.idex_rd >= 5'd3 && u_chain.idex_rd <= 5'd8) begin
                // add xN, x(N-1), x(N-2): rs1 from EX/MEM, rs2 from MEM/WB
                if (u_chain.forward_a != 2'b10 || u_chain.forward_b != 2'b01)
                    $fatal(1, "u_chain: x%0d forwarding a=%b b=%b", u_chain.idex_rd,
                           u_chain.forward_a, u_chain.forward_b);
                chain_seen[3'(u_chain.idex_rd - 5'd3)] <= 1'b1;
            end
            if (u_chain.idex_reg_write && u_chain.idex_rd == 5'd9) begin
                // add x9, x8, x6: x6 arrives through the WB->ID bypass, not EX forwarding
                if (u_chain.forward_a != 2'b10 || u_chain.forward_b != 2'b00 ||
                    u_chain.idex_rs2_data != 32'd8)
                    $fatal(1, "u_chain: x9 a=%b b=%b rs2_data=%0d", u_chain.forward_a,
                           u_chain.forward_b, u_chain.idex_rs2_data);
                chain_seen[6] <= 1'b1;
            end
            if (u_chain.idex_reg_write && u_chain.idex_rd == 5'd11) begin
                // sub x11, x10, x9: younger x10 (EX/MEM) beats older x10 (MEM/WB)
                if (u_chain.forward_a != 2'b10 || u_chain.ex_forwarded_rs1 != 32'hFFFF_FFFF)
                    $fatal(1, "u_chain: x11 a=%b rs1=%h", u_chain.forward_a,
                           u_chain.ex_forwarded_rs1);
                chain_seen[7] <= 1'b1;
            end

            // ---- Wrong-path suppression ----
            if (u_br.wb_reg_write && (u_br.wb_rd == 5'd6 || u_br.wb_rd == 5'd9))
                $fatal(1, "u_br: wrong-path write to x%0d reached WB", u_br.wb_rd);
            if (u_br.exmem_mem_write)
                $fatal(1, "u_br: wrong-path store reached MEM");
            if (u_br.wb_reg_write && u_br.wb_rd == 5'd3)
                br_x3_writes <= br_x3_writes + 1;
            if (u_lu.wb_reg_write && u_lu.wb_rd == 5'd9)
                $fatal(1, "u_lu: wrong-path write to x9 reached WB");
            if (u_x0.load_use_stall)
                $fatal(1, "u_x0: load to x0 caused a load-use stall");
            // Checked every cycle: trailing NOPs (addi x0,x0,0) would write 0
            // back into entry 0 and hide a corrupted x0 at end of test.
            if (u_x0.u_register_file.registers[0] !== x0_reg0_after_reset)
                $fatal(1, "u_x0: register file entry 0 written (now %h)",
                       u_x0.u_register_file.registers[0]);
        end

        if (rst_n_mid && rst_restarted && u_rst.wb_reg_write && u_rst.wb_rd != 5'd0) begin
            if (u_rst.wb_rd != 5'(rst_writes_after_restart + 1))
                $fatal(1, "u_rst: write-back x%0d out of order after restart", u_rst.wb_rd);
            rst_writes_after_restart <= rst_writes_after_restart + 1;
        end
    end

    initial begin
        clk = 1'b0;
        rst_n = 1'b0;
        rst_n_mid = 1'b0;
        fwd_seen = '0;
        chain_seen = '0;
        br_x3_writes = 0;
        rst_writes_after_restart = 0;
        rst_restarted = 1'b0;

        $dumpfile("simulation/pipeline_corner_tb.vcd");
        $dumpvars(0, pipeline_corner_tb);

        // ---- Cold reset: held for two edges, every instance must be clean ----
        repeat (2) @(posedge clk);
        #1;
        `EXPECT_RESET_STATE(u_x0)
        `EXPECT_RESET_STATE(u_fwd)
        `EXPECT_RESET_STATE(u_chain)
        `EXPECT_RESET_STATE(u_lu)
        `EXPECT_RESET_STATE(u_br)
        `EXPECT_RESET_STATE(u_rst)
        `EXPECT_RESET_STATE(u_rst_ref)
        x0_reg0_after_reset = u_x0.u_register_file.registers[0];
        $display("PASS: cold reset clears PC, pipeline controls and counters");

        @(negedge clk);
        #2;
        rst_n = 1'b1;
        rst_n_mid = 1'b1;

        // ---- Mid-program reset of u_rst while SW x1 is in EX/MEM ----
        do @(negedge clk); while (!u_rst.exmem_mem_write);
        if (u_rst.exmem_alu_result != 32'h10 || u_rst.exmem_store_data != 32'h123)
            $fatal(1, "u_rst: unexpected store in flight addr=%h data=%h",
                   u_rst.exmem_alu_result, u_rst.exmem_store_data);
        if (!(u_rst.wb_reg_write && u_rst.wb_rd == 5'd2))
            $fatal(1, "u_rst: expected ADDI x2 write-back in flight at reset");
        for (int r = 1; r <= 5; r++)
            rst_snapshot[r] = u_rst.u_register_file.registers[r];
        #2;
        rst_n_mid = 1'b0;   // asynchronous assertion, between clock edges
        #1;
        if (u_rst.pc_current !== 32'd0)
            $fatal(1, "u_rst: PC did not reset asynchronously (pc=%h)", u_rst.pc_current);
        repeat (3) begin
            @(posedge clk);
            #1;
            `EXPECT_RESET_STATE(u_rst)
            `EXPECT_MEM(u_rst, 4, 0)
            for (int r = 1; r <= 5; r++)
                if (u_rst.u_register_file.registers[r] !== rst_snapshot[r])
                    $fatal(1, "u_rst: x%0d changed while reset was held", r);
        end
        if (rst_snapshot[1] !== 32'h123)
            $fatal(1, "u_rst: x1 should have been written before reset");
        $display("PASS: mid-program reset suppresses in-flight store and register write");
        @(negedge clk);
        #2;
        rst_restarted = 1'b1;
        rst_n_mid = 1'b1;

        repeat (45) @(negedge clk);
        #1;

        // ---- x0 protection ----
        if (u_x0.u_register_file.registers[0] !== x0_reg0_after_reset)
            $fatal(1, "u_x0: register file entry 0 was written");
        `EXPECT_REG(u_x0, 1, 0)
        `EXPECT_REG(u_x0, 2, 0)
        `EXPECT_REG(u_x0, 3, 0)
        `EXPECT_REG(u_x0, 4, 9)
        `EXPECT_REG(u_x0, 5, 9)
        `EXPECT_REG(u_x0, 6, 9)
        `EXPECT_MEM(u_x0, 0, 9)
        `EXPECT_COUNTERS(u_x0, x0_se, x0_fe, 10, 0, 0, 0)
        $display("PASS: x0 writes discarded; x0 never forwarded, bypassed or load-use stalled");

        // ---- Forwarding priority ----
        `EXPECT_REG(u_fwd, 1, 2)
        `EXPECT_REG(u_fwd, 2, 4)
        `EXPECT_REG(u_fwd, 6, 2)
        `EXPECT_REG(u_fwd, 10, -8)
        `EXPECT_REG(u_fwd, 11, 200)
        `EXPECT_REG(u_fwd, 12, -200)
        `EXPECT_REG(u_fwd, 14, 32'h66)
        `EXPECT_MEM(u_fwd, 1, 32'h66)
        `EXPECT_MEM(u_fwd, 2, 11)
        if (fwd_seen != 6'b111111)
            $fatal(1, "u_fwd: forwarding scenario not observed: %b", fwd_seen);
        `EXPECT_COUNTERS(u_fwd, fwd_se, fwd_fe, 17, 0, 0, 0)
        $display("PASS: forwarding priority EX/MEM over MEM/WB for rs1, rs2, store data and base");

        // ---- Consecutive dependent instructions ----
        `EXPECT_REG(u_chain, 3, 2)
        `EXPECT_REG(u_chain, 4, 3)
        `EXPECT_REG(u_chain, 5, 5)
        `EXPECT_REG(u_chain, 6, 8)
        `EXPECT_REG(u_chain, 7, 13)
        `EXPECT_REG(u_chain, 8, 21)
        `EXPECT_REG(u_chain, 9, 29)
        `EXPECT_REG(u_chain, 10, 32'hFFFF_FFFF)
        `EXPECT_REG(u_chain, 11, -30)
        if (chain_seen != 8'hFF)
            $fatal(1, "u_chain: forwarding scenario not observed: %b", chain_seen);
        `EXPECT_COUNTERS(u_chain, chain_se, chain_fe, 12, 0, 0, 0)
        $display("PASS: 10-deep dependent chain with dual-source forwarding and WB->ID bypass");

        // ---- Load-use stalls ----
        `EXPECT_REG(u_lu, 3, 4)
        `EXPECT_REG(u_lu, 4, 12)
        `EXPECT_REG(u_lu, 5, 16)
        `EXPECT_REG(u_lu, 6, 12)
        `EXPECT_REG(u_lu, 7, 4)
        `EXPECT_REG(u_lu, 8, 12)
        `EXPECT_REG(u_lu, 9, 0)
        `EXPECT_REG(u_lu, 10, 4)
        `EXPECT_REG(u_lu, 11, 10)
        `EXPECT_REG(u_lu, 12, 8)
        `EXPECT_MEM(u_lu, 0, 4)
        `EXPECT_MEM(u_lu, 1, 12)
        `EXPECT_MEM(u_lu, 2, 12)
        `EXPECT_MEM(u_lu, 3, 4)
        `EXPECT_COUNTERS(u_lu, lu_se, lu_fe, 16, 5, 1, 0)
        $display("PASS: load-use stalls on load base, rs2, store data, store base and branch; no false stalls");

        // ---- Branch flushing / write suppression ----
        `EXPECT_REG(u_br, 1, 0)
        `EXPECT_REG(u_br, 2, 3)
        `EXPECT_REG(u_br, 3, 1)
        `EXPECT_REG(u_br, 4, 6)
        `EXPECT_REG(u_br, 5, 6)
        `EXPECT_REG(u_br, 6, 0)
        `EXPECT_REG(u_br, 7, 0)
        `EXPECT_REG(u_br, 9, 0)
        `EXPECT_REG(u_br, 10, 6)
        `EXPECT_MEM(u_br, 0, 0)
        if (br_x3_writes != 2)  // addi x3,x0,0 once + shadow addi x3,x3,1 once
            $fatal(1, "u_br: expected 2 writes to x3, observed %0d", br_x3_writes);
        `EXPECT_COUNTERS(u_br, br_se, br_fe, 19, 0, 4, 1)
        $display("PASS: loop and forward-operand branches flush wrong-path ALU, store and branch");

        // ---- Reset restart equivalence ----
        `EXPECT_REG(u_rst, 1, 32'h123)
        `EXPECT_REG(u_rst, 2, 32'h10)
        `EXPECT_REG(u_rst, 3, 32'h246)
        `EXPECT_REG(u_rst, 4, 32'h123)
        `EXPECT_REG(u_rst, 5, 32'h369)
        `EXPECT_MEM(u_rst, 4, 32'h123)
        if (rst_writes_after_restart != 5)
            $fatal(1, "u_rst: expected 5 ordered write-backs after restart, saw %0d",
                   rst_writes_after_restart);
        `EXPECT_COUNTERS(u_rst, rst_se, rst_fe, 6, 1, 0, 0)
        if (u_rst.perf_total_cycles != u_rst_ref.perf_total_cycles ||
            u_rst.perf_instructions_retired != u_rst_ref.perf_instructions_retired)
            $fatal(1, "u_rst: restarted run differs from cold-start reference (cycles %0d vs %0d)",
                   u_rst.perf_total_cycles, u_rst_ref.perf_total_cycles);
        for (int r = 1; r <= 5; r++)
            if (u_rst.u_register_file.registers[r] !== u_rst_ref.u_register_file.registers[r])
                $fatal(1, "u_rst: x%0d differs from cold-start reference", r);
        $display("PASS: restart after mid-program reset matches cold-start reference");

        $display("PIPELINE CORNER-CASE TESTS PASSED");
        $finish;
    end
endmodule
